import type { Vec3 } from '../contracts/math';
import {
  addVec3,
  cloneVec3,
  dotVec3,
  normalizeVec3,
  rotateAroundY,
  scaleVec3,
  subVec3,
  vec3,
} from './vec';

export type RotatingKind = 'bar' | 'windmill' | 'spinner' | 'pendulum';

export interface RotatingConfig {
  id: string;
  kind: RotatingKind;
  center: Vec3;
  armLength: number;
  speed: number;
  phase?: number;
  clockwise?: boolean;
  swingAngle?: number;
  enabled?: boolean;
}

/** Pendulums swing this far to each side unless the hole overrides it. */
const DEFAULT_SWING_ANGLE = Math.PI / 3;

function finite(value: number | undefined, fallback = 0): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function isFiniteVec3(v: Vec3 | null | undefined): boolean {
  return !!v && Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z);
}

function spinSign(config: RotatingConfig): number {
  return config.clockwise === true ? -1 : 1;
}

/** Disabled obstacles keep their pose but stop moving. */
function activeSpeed(config: RotatingConfig): number {
  return config.enabled === false ? 0 : finite(config.speed);
}

export function rotationAngle(config: RotatingConfig, elapsed: number): number {
  const phase = finite(config.phase);
  const speed = activeSpeed(config);
  if (speed === 0) return phase;
  const time = finite(elapsed);
  if (config.kind === 'pendulum') {
    const swing = finite(config.swingAngle, DEFAULT_SWING_ANGLE);
    return phase + swing * Math.sin(speed * time);
  }
  return phase + spinSign(config) * speed * time;
}

export function armTipPosition(config: RotatingConfig, elapsed: number): Vec3 {
  const center = isFiniteVec3(config.center) ? cloneVec3(config.center) : vec3();
  const arm = vec3(finite(config.armLength), 0, 0);
  return addVec3(center, rotateAroundY(arm, rotationAngle(config, elapsed)));
}

/** d(angle)/dt around the Y axis. */
function angularVelocity(config: RotatingConfig, elapsed: number): number {
  const speed = activeSpeed(config);
  if (speed === 0) return 0;
  const time = finite(elapsed);
  if (config.kind === 'pendulum') {
    const swing = finite(config.swingAngle, DEFAULT_SWING_ANGLE);
    return swing * speed * Math.cos(speed * time);
  }
  return spinSign(config) * speed;
}

export function surfaceVelocityAt(config: RotatingConfig, point: Vec3, elapsed: number): Vec3 {
  const omega = angularVelocity(config, elapsed);
  if (omega === 0 || !isFiniteVec3(point) || !isFiniteVec3(config.center)) return vec3();
  const radius = subVec3(point, config.center);
  return { x: omega * radius.z, y: 0, z: -omega * radius.x };
}

/**
 * Reflects the ball off the arm segment center..tip and adds the arm surface speed.
 * Returns null when the ball is further than hitRadius from that segment horizontally.
 */
export function deflectBall(
  config: RotatingConfig,
  position: Vec3,
  velocity: Vec3,
  elapsed: number,
  hitRadius: number,
): Vec3 | null {
  if (config.enabled === false) return null;
  if (!isFiniteVec3(position) || !isFiniteVec3(velocity) || !isFiniteVec3(config.center)) return null;
  if (!Number.isFinite(hitRadius) || hitRadius <= 0) return null;

  const center = config.center;
  const tip = armTipPosition(config, elapsed);
  const armX = tip.x - center.x;
  const armZ = tip.z - center.z;
  const armLengthSq = armX * armX + armZ * armZ;

  const toBallX = position.x - center.x;
  const toBallZ = position.z - center.z;
  let along = armLengthSq > 1e-12 ? (toBallX * armX + toBallZ * armZ) / armLengthSq : 0;
  along = Math.min(1, Math.max(0, along));

  const offsetX = position.x - (center.x + armX * along);
  const offsetZ = position.z - (center.z + armZ * along);
  if (Math.hypot(offsetX, offsetZ) > hitRadius) return null;

  const armDir = normalizeVec3(vec3(armX, 0, armZ)) ?? vec3(1, 0, 0);
  let normal = vec3(-armDir.z, 0, armDir.x);
  if (offsetX * normal.x + offsetZ * normal.z < 0) normal = scaleVec3(normal, -1);

  const reflected = subVec3(velocity, scaleVec3(normal, 2 * dotVec3(velocity, normal)));
  return addVec3(reflected, surfaceVelocityAt(config, position, elapsed));
}
