import { describe, expect, it } from 'vitest';
import type { Vec3 } from '../contracts/math';
import {
  armTipPosition,
  deflectBall,
  rotationAngle,
  surfaceVelocityAt,
  type RotatingConfig,
} from './rotating';

function spinner(overrides: Partial<RotatingConfig> = {}): RotatingConfig {
  return {
    id: 'spin-1',
    kind: 'spinner',
    center: { x: 0, y: 0, z: 0 },
    armLength: 2,
    speed: 4,
    ...overrides,
  };
}

function speedOf(v: Vec3): number {
  return Math.hypot(v.x, v.y, v.z);
}

describe('rotationAngle', () => {
  it('advances linearly with elapsed time', () => {
    const bar = spinner({ kind: 'bar', speed: 2, phase: 0.5 });
    expect(rotationAngle(bar, 0)).toBeCloseTo(0.5, 10);
    expect(rotationAngle(bar, 1)).toBeCloseTo(2.5, 10);
    expect(rotationAngle(bar, 3)).toBeCloseTo(6.5, 10);
  });

  it('flips the sign when clockwise is set', () => {
    const ccw = spinner({ kind: 'windmill', speed: 2 });
    const cw = spinner({ kind: 'windmill', speed: 2, clockwise: true });
    expect(rotationAngle(ccw, 2)).toBeCloseTo(4, 10);
    expect(rotationAngle(cw, 2)).toBeCloseTo(-4, 10);
  });

  it('keeps a pendulum inside its swing angle and freezes on zero or invalid input', () => {
    const swing = Math.PI / 4;
    const pendulum = spinner({ kind: 'pendulum', speed: 3, phase: 1, swingAngle: swing });
    for (let step = 0; step <= 60; step += 1) {
      const angle = rotationAngle(pendulum, step * 0.05);
      expect(Math.abs(angle - 1)).toBeLessThanOrEqual(swing + 1e-9);
    }
    expect(rotationAngle(pendulum, Number.NaN)).toBeCloseTo(1, 10);
    expect(rotationAngle(spinner({ speed: 0, phase: 1 }), 5)).toBeCloseTo(1, 10);
    expect(rotationAngle(spinner({ phase: 1, enabled: false }), 5)).toBeCloseTo(1, 10);
  });
});

describe('armTipPosition', () => {
  it('places the tip an arm length away, rotated right handed around Y', () => {
    const config = spinner({ center: { x: 1, y: 2, z: -1 }, armLength: 3, speed: 0, phase: 0 });
    const atRest = armTipPosition(config, 0);
    expect(atRest.x).toBeCloseTo(4, 10);
    expect(atRest.y).toBeCloseTo(2, 10);
    expect(atRest.z).toBeCloseTo(-1, 10);

    const quarter = armTipPosition({ ...config, phase: Math.PI / 2 }, 0);
    expect(quarter.x).toBeCloseTo(1, 10);
    expect(quarter.y).toBeCloseTo(2, 10);
    expect(quarter.z).toBeCloseTo(-4, 10);
  });
});

describe('surfaceVelocityAt', () => {
  it('returns the tangential velocity around the center', () => {
    const config = spinner({ speed: 2, phase: 0 });
    const velocity = surfaceVelocityAt(config, { x: 1, y: 0, z: 0 }, 0);
    expect(velocity.x).toBeCloseTo(0, 10);
    expect(velocity.y).toBeCloseTo(0, 10);
    expect(velocity.z).toBeCloseTo(-2, 10);

    const still = surfaceVelocityAt(spinner({ speed: 0 }), { x: 1, y: 0, z: 0 }, 0);
    expect(still).toEqual({ x: 0, y: 0, z: 0 });
  });
});

describe('deflectBall', () => {
  it('returns null outside the hit radius or for invalid input', () => {
    const config = spinner({ speed: 0, phase: 0 });
    const far = deflectBall(config, { x: 1, y: 0, z: 0.9 }, { x: 0, y: 0, z: -1 }, 0, 0.2);
    expect(far).toBeNull();

    const beyondTip = deflectBall(config, { x: 3, y: 0, z: 0 }, { x: -1, y: 0, z: 0 }, 0, 0.2);
    expect(beyondTip).toBeNull();

    expect(deflectBall(config, { x: 1, y: 0, z: Number.NaN }, { x: 0, y: 0, z: -1 }, 0, 0.2)).toBeNull();
    expect(deflectBall(config, { x: 1, y: 0, z: 0.1 }, { x: 0, y: 0, z: -1 }, 0, 0)).toBeNull();
    expect(
      deflectBall({ ...config, enabled: false }, { x: 1, y: 0, z: 0.1 }, { x: 0, y: 0, z: -1 }, 0, 0.2),
    ).toBeNull();
  });

  it('mirrors the velocity about the arm normal when the arm is still', () => {
    const config = spinner({ speed: 0, phase: 0 });
    const result = deflectBall(config, { x: 1, y: 0, z: 0.1 }, { x: 0.5, y: 0, z: -1 }, 0, 0.2);
    expect(result).not.toBeNull();
    expect(result!.x).toBeCloseTo(0.5, 10);
    expect(result!.y).toBeCloseTo(0, 10);
    expect(result!.z).toBeCloseTo(1, 10);
  });

  it('adds the arm surface speed on a hit', () => {
    const incoming = { x: 0, y: 0, z: -1 };
    const config = spinner({ speed: 4, phase: 0 });
    const result = deflectBall(config, { x: 1, y: 0, z: 0.1 }, incoming, 0, 0.2);
    expect(result).not.toBeNull();
    expect(result!.x).toBeCloseTo(0.4, 10);
    expect(result!.z).toBeCloseTo(-3, 10);
    expect(speedOf(result!)).toBeGreaterThan(speedOf(incoming));
  });
});
